mapper.select:

WHERE M.DICT_ID = #{dictId}
AND M.MAP_TP = #{mapTp} 

  AND (M.OLD_NM ILIKE '%' || #{keyword} || '%' OR M.OLD_ENG_ABRV_NM ILIKE '%' || #{keyword} || '%'
       OR W.WORD_NM ILIKE '%' || #{keyword} || '%' OR T.TERMS_NM ILIKE '%' || #{keyword} || '%')

ORDER BY M.MAP_TP, M.OLD_NM

SELECT COUNT(*) FROM TB_STD_MAP
 WHERE DICT_ID = #{dictId} AND MAP_TP = #{mapTp} AND OLD_NM = #{oldNm}
   AND MAP_ID <> COALESCE(#{mapId, jdbcType=VARCHAR}, '')

mapper.update:
UPDATE TB_STD_MAP
   SET MAP_TP = #{mapTp}, OLD_NM = #{oldNm}, OLD_ENG_ABRV_NM = NULLIF(#{oldEngAbrvNm, jdbcType=VARCHAR}, ''),
       NEW_ID = #{newId}, MAP_REASON = NULLIF(#{mapReason, jdbcType=VARCHAR}, ''),
       UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS'), UPDT_USER_ID = #{userId}
 WHERE MAP_ID = #{mapId}
